def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    if not b:
        return sorted(a)

    # Merge overlapping/touching intervals in both lists
    def merge_intervals(intervals):
        if not intervals:
            return []
        sorted_intervals = sorted(intervals)
        merged = [sorted_intervals[0]]
        for start, end in sorted_intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    return sorted(result)

